arguments.command:
cd /workspace && python3 - <<'PY'
import sys,random,time
sys.path.insert(0,'/workspace/submission');sys.path.insert(0,'/workspace/tmp')
from compiler import compile_plan, find_deficient_cut
from compiler_proto import validate_plan
random.seed(2024)
t0=time.time();prep=den=0
for it in range(3000):
 n=random.randint(2,13)
 np=random.randint(2,min(8,n))
 C=sorted(random.sample(range(n),np))
 roots={v:random.choice([0,0,1,2,3,5,10]) for v in C}
 if sum(roots.values())==0:roots[C[0]]=1
 links=[]
 for u in range(n):
  for v in range(u+1,n):
   if random.random()<0.4:links.append((u,v) if random.random()<.5 else (v,u))
 env={i:random.choice([0,0,1,1,2,3,5]) for i in range(len(links))}
 p=random.choice([1,2,3])
 try:
  cut=find_deficient_cut(n,links,C,roots,p,env)
  out,payload=compile_plan(n,links,C,roots,p,env)
  if cut is not None:
   assert out=='denied';den+=1
  else:
   assert out=='prepared',(out,payload)
   validate_plan(payload,n,links,C,roots,p,env);prep+=1
 except Exception as e:
  print('FAIL',it,n,C,roots,links,env,p,'cut',cut,repr(e));raise
 if it%1000==0:print(it,prep,den,round(time.time()-t0,2),flush=True)
print('DONE',prep,den,time.time()-t0)
PY
